const e=[{id:"musculoskeletal-diseases-001",topicId:"musculoskeletal-diseases",question:"Что такое остеопороз?",options:["Боковое искривление позвоночника","Метаболическое заболевание скелета с уменьшением плотности костной ткани","Разрушение суставного хряща","Воспаление кости и костного мозга"],correctIndex:1,explanation:"Остеопороз — метаболическое заболевание скелета, при котором уменьшается плотность костной ткани.",difficulty:"easy",tags:["остеопороз"]},{id:"musculoskeletal-diseases-002",topicId:"musculoskeletal-diseases",question:"Что означает греческое слово «poros» в термине «остеопороз»?",options:["Отверстие","Хрупкость","Кость","Воспаление"],correctIndex:0,explanation:"Остеопороз — от греч. osteo — кость, poros — отверстие.",difficulty:"medium",tags:["остеопороз","терминология"]},{id:"musculoskeletal-diseases-003",topicId:"musculoskeletal-diseases",question:"Каковы последствия уменьшения плотности костной ткани при остеопорозе?",options:["Кости срастаются между собой","Кости увеличиваются в размерах","Кости становятся более гибкими","Кости становятся хрупкими и ломаются даже при небольшой нагрузке"],correctIndex:3,explanation:"При остеопорозе кости становятся более хрупкими, легко деформируются и могут ломаться даже при небольшой нагрузке.",difficulty:"easy",tags:["остеопороз"]},{id:"musculoskeletal-diseases-004",topicId:"musculoskeletal-diseases",question:"Дефицит какого витамина указан среди причин остеопороза?",options:["Витамина C","Витамина B12","Витамина K","Витамина D"],correctIndex:3,explanation:"Причины остеопороза включают дефицит витамина D и нарушение обмена кальция.",difficulty:"easy",tags:["остеопороз","причины"]},{id:"musculoskeletal-diseases-005",topicId:"musculoskeletal-diseases",question:"Что указано среди причин остеопороза?",options:["Чрезмерная физическая активность","Избыток массы тела","Избыток половых гормонов","Недостаток половых гормонов и малоподвижный образ жизни"],correctIndex:3,explanation:"Причины остеопороза: снижение массы тела, недостаток половых гормонов, малоподвижный образ жизни, курение, алкоголь, дефицит витамина D, нарушение обмена кальция, заболевания щитовидной и околощитовидных желёз.",difficulty:"medium",tags:["остеопороз","причины"]},{id:"musculoskeletal-diseases-006",topicId:"musculoskeletal-diseases",question:"Заболевания каких желёз названы среди причин остеопороза?",options:["Потовых и сальных","Слюнных","Молочных","Щитовидной и околощитовидных"],correctIndex:3,explanation:"Среди причин остеопороза указаны заболевания щитовидной и околощитовидных желёз.",difficulty:"medium",tags:["остеопороз","причины"]},{id:"musculoskeletal-diseases-007",topicId:"musculoskeletal-diseases",question:"Что НЕ относится к последствиям остеопороза по лекции?",options:["Боли в костях и позвоночнике","Частые переломы","Повышение плотности костей","Деформация скелета"],correctIndex:2,explanation:"Последствия остеопороза: повышенная ломкость костей, частые переломы, деформация скелета, боли в костях и позвоночнике.",difficulty:"medium",tags:["остеопороз"]},{id:"musculoskeletal-diseases-008",topicId:"musculoskeletal-diseases",question:"Что такое протрузия межпозвоночного диска?",options:["Перелом тела позвонка","Выпячивание диска за пределы тела позвонка без разрыва фиброзного кольца","Разрыв фиброзного кольца с выходом пульпозного ядра","Воспаление сустава"],correctIndex:1,explanation:"Протрузия — выпячивание межпозвоночного диска за пределы тела позвонка без разрыва фиброзного кольца.",difficulty:"medium",tags:["протрузия"]},{id:"musculoskeletal-diseases-009",topicId:"musculoskeletal-diseases",question:"Какова обычная величина выпячивания при протрузии?",options:["15–20 мм","1–2 мм","5–6 мм","Более 3 см"],correctIndex:2,explanation:"Обычно выпячивание при протрузии составляет 5–6 мм.",difficulty:"hard",tags:["протрузия","числовые данные"]},{id:"musculoskeletal-diseases-010",topicId:"musculoskeletal-diseases",question:"Какой стадией считается протрузия?",options:["Видом артрита","Формой сколиоза","Конечной стадией остеопороза","Начальной стадией межпозвоночной грыжи"],correctIndex:3,explanation:"Протрузия считается начальной стадией межпозвоночной грыжи.",difficulty:"medium",tags:["протрузия"]},{id:"musculoskeletal-diseases-011",topicId:"musculoskeletal-diseases",question:"Что указано среди причин протрузии?",options:["Бактериальная инфекция","Наследственность, травмы, сильные нагрузки, нарушение осанки","Повышенный сахар крови","Дефицит йода"],correctIndex:1,explanation:"Причины протрузии: наследственность, травмы позвоночника, сильные физические нагрузки, нарушение осанки, малоподвижный образ жизни.",difficulty:"medium",tags:["протрузия","причины"]},{id:"musculoskeletal-diseases-012",topicId:"musculoskeletal-diseases",question:"Как называется стадия, следующая за протрузией, с разрывом фиброзного кольца?",options:["Остеохондроз","Артроз","Экструзия (грыжа)","Остеомиелит"],correctIndex:2,explanation:"Развитие заболевания: 1 — протрузия (выпячивание диска), 2 — экструзия (грыжа) — разрыв фиброзного кольца и выход пульпозного ядра.",difficulty:"medium",tags:["грыжа"]},{id:"musculoskeletal-diseases-013",topicId:"musculoskeletal-diseases",question:"Что происходит при межпозвоночной грыже?",options:["Разрыв фиброзного кольца и выход пульпозного ядра","Срастание позвонков","Выпячивание диска без разрыва кольца","Уменьшение плотности позвонков"],correctIndex:0,explanation:"Межпозвоночная грыжа — разрыв фиброзного кольца межпозвоночного диска и выход пульпозного ядра.",difficulty:"easy",tags:["грыжа"]},{id:"musculoskeletal-diseases-014",topicId:"musculoskeletal-diseases",question:"Какой симптом характерен для межпозвоночной грыжи?",options:["Гематурия","Экзофтальм","Иррадиация боли в руку или ногу","Светобоязнь"],correctIndex:2,explanation:"Симптомы грыжи: сильная боль в позвоночнике, иррадиация боли в руку или ногу, ограничение движений, онемение и слабость в конечностях.",difficulty:"medium",tags:["грыжа","симптомы"]},{id:"musculoskeletal-diseases-015",topicId:"musculoskeletal-diseases",question:"Что указано среди причин межпозвоночной грыжи?",options:["Дефицит витамина C","Вирусная инфекция","Избыток пролактина","Поднятие тяжестей и резкие движения"],correctIndex:3,explanation:"Причины грыжи: возрастные изменения, поднятие тяжестей, резкие движения, травмы позвоночника.",difficulty:"medium",tags:["грыжа","причины"]},{id:"musculoskeletal-diseases-016",topicId:"musculoskeletal-diseases",question:"Что такое остеомиелит?",options:["Воспаление сустава","Воспаление кости и костного мозга","Разрушение суставного хряща","Воспаление костной ткани без костного мозга"],correctIndex:1,explanation:"Остеомиелит — воспаление кости и костного мозга.",difficulty:"medium",tags:["другие заболевания"]},{id:"musculoskeletal-diseases-017",topicId:"musculoskeletal-diseases",question:"Что такое остит?",options:["Дегенерация межпозвоночных дисков","Воспаление костной ткани","Воспаление кости и костного мозга","Воспаление сустава"],correctIndex:1,explanation:"Остит — воспаление костной ткани.",difficulty:"medium",tags:["другие заболевания"]},{id:"musculoskeletal-diseases-018",topicId:"musculoskeletal-diseases",question:"Что такое артрит?",options:["Разрушение суставного хряща","Уменьшение плотности кости","Воспаление сустава","Воспаление костной ткани"],correctIndex:2,explanation:"Артрит — воспаление сустава.",difficulty:"easy",tags:["другие заболевания"]},{id:"musculoskeletal-diseases-019",topicId:"musculoskeletal-diseases",question:"Что такое артроз?",options:["Воспаление сустава","Боковое искривление позвоночника","Разрушение суставного хряща","Воспаление кости и костного мозга"],correctIndex:2,explanation:"Артроз — разрушение суставного хряща.",difficulty:"medium",tags:["другие заболевания"]},{id:"musculoskeletal-diseases-020",topicId:"musculoskeletal-diseases",question:"Как в лекции определён остеоартрит?",options:["Уменьшение плотности кости","Разрушение межпозвоночных дисков","Воспаление костей и суставов","Воспаление костного мозга"],correctIndex:2,explanation:"Остеоартрит — воспаление костей и суставов.",difficulty:"hard",tags:["другие заболевания"]},{id:"musculoskeletal-diseases-021",topicId:"musculoskeletal-diseases",question:"Что такое остеохондроз?",options:["Воспаление костного мозга","Воспаление сустава","Дегенеративное заболевание позвоночника с поражением межпозвоночных дисков","Перелом позвонка"],correctIndex:2,explanation:"Остеохондроз — дегенеративное заболевание позвоночника с поражением межпозвоночных дисков.",difficulty:"medium",tags:["другие заболевания"]},{id:"musculoskeletal-diseases-022",topicId:"musculoskeletal-diseases",question:"Какие методы используют для диагностики заболеваний костно-мышечной системы согласно лекции?",options:["Цистоскопию и УЗИ почек","Рентгенографию, КТ, МРТ","ЭЭГ и люмбальную пункцию","ПАП-тест и кольпоскопию"],correctIndex:1,explanation:"Для диагностики используют рентгенографию, КТ (компьютерную томографию) и МРТ (магнитно-резонансную томографию).",difficulty:"easy",tags:["диагностика"]},{id:"musculoskeletal-diseases-023",topicId:"musculoskeletal-diseases",question:"Какой буквой обозначают шейный отдел позвоночника?",options:["S","C","L","T"],correctIndex:1,explanation:"Шейный отдел — Cervical vertebrae — C.",difficulty:"medium",tags:["отделы позвоночника","латынь"]},{id:"musculoskeletal-diseases-024",topicId:"musculoskeletal-diseases",question:"Какой отдел позвоночника обозначается буквой L?",options:["Крестцовый","Грудной","Шейный","Поясничный"],correctIndex:3,explanation:"Поясничный отдел — Lumbar vertebrae — L.",difficulty:"medium",tags:["отделы позвоночника","латынь"]},{id:"musculoskeletal-diseases-025",topicId:"musculoskeletal-diseases",question:"Как обозначают грудной отдел позвоночника?",options:["S (Sacrum)","C (Cervical vertebrae)","T (Thoracic vertebrae)","Co (Coccyx)"],correctIndex:2,explanation:"Грудной отдел — Thoracic vertebrae — T.",difficulty:"medium",tags:["отделы позвоночника","латынь"]},{id:"musculoskeletal-diseases-026",topicId:"musculoskeletal-diseases",question:"Какое обозначение соответствует копчиковому отделу позвоночника?",options:["S (Sacrum)","L (Lumbar)","C (Cervical)","Co (Coccyx)"],correctIndex:3,explanation:"Копчиковый отдел — Coccyx — Co; крестцовый — Sacrum — S.",difficulty:"hard",tags:["отделы позвоночника","латынь"]},{id:"musculoskeletal-diseases-027",topicId:"musculoskeletal-diseases",question:"Какие препараты применяют при воспалительных заболеваниях опорно-двигательной системы?",options:["Антибиотики, НПВС, глюкокортикостероиды","Спазмолитики и диуретики","Только иммобилизацию","Только витамин D"],correctIndex:0,explanation:"При воспалительных заболеваниях: антибиотики, НПВС, глюкокортикостероиды.",difficulty:"medium",tags:["лечение"]},{id:"musculoskeletal-diseases-028",topicId:"musculoskeletal-diseases",question:"Какой метод лечения применяют при травмах опорно-двигательной системы?",options:["Гемодиализ","Иммобилизацию (гипс) и хирургическое лечение","Только хондропротекторы","Только антибиотики"],correctIndex:1,explanation:"При травмах: иммобилизация (гипс) и хирургическое лечение.",difficulty:"easy",tags:["лечение"]},{id:"musculoskeletal-diseases-029",topicId:"musculoskeletal-diseases",question:"Какие вещества содержат препараты, применяемые при заболеваниях костей?",options:["Инсулин и глюкагон","Кальций, витамин D, хондроитин сульфат","Йод и селен","Железо и фолиевую кислоту"],correctIndex:1,explanation:"При заболеваниях костей используют препараты, содержащие кальций, витамин D, хондроитин сульфат.",difficulty:"medium",tags:["лечение","хондропротекторы"]},{id:"musculoskeletal-diseases-030",topicId:"musculoskeletal-diseases",question:"Как в лекции называют препараты с кальцием, витамином D и хондроитин сульфатом?",options:["Спазмолитиками","Уросептиками","Ноотропами","Хондропротекторами"],correctIndex:3,explanation:"Препараты, содержащие кальций, витамин D и хондроитин сульфат, в лекции названы хондропротекторами.",difficulty:"medium",tags:["лечение","хондропротекторы"]},{id:"musculoskeletal-diseases-031",topicId:"musculoskeletal-diseases",question:"Какой препарат приведён в лекции как пример хондропротектора?",options:["Фитолизин","Уролесан","Терафлекс","Канефрон"],correctIndex:2,explanation:"Примеры хондропротекторов в лекции: Кальций D3 Никомед, Кальцемин, Терафлекс, Артифлекс, Хондромед, Хондроксид.",difficulty:"medium",tags:["препараты","торговые названия"]},{id:"musculoskeletal-diseases-032",topicId:"musculoskeletal-diseases",question:"Кальцемин упоминается в лекции как препарат при заболеваниях чего?",options:["Почек и мочевых путей","Органа слуха","Костей","Нервной системы"],correctIndex:2,explanation:"Кальцемин приведён среди примеров препаратов, применяемых при заболеваниях костей.",difficulty:"easy",tags:["препараты","торговые названия"]},{id:"musculoskeletal-diseases-033",topicId:"musculoskeletal-diseases",question:"Выберите препарат из того же списка примеров, что Артифлекс и Хондромед.",options:["Гранноза","Хондроксид","Роватинекс","Уролизин"],correctIndex:1,explanation:"Артифлекс, Хондромед и Хондроксид — примеры хондропротекторов; Гранноза, Роватинекс и Уролизин — препараты в урологии.",difficulty:"medium",tags:["препараты","торговые названия"]},{id:"musculoskeletal-diseases-034",topicId:"musculoskeletal-diseases",question:"Что из перечисленного НЕ является примером хондропротектора в лекции?",options:["Канефрон","Кальцемин","Артифлекс","Хондромед"],correctIndex:0,explanation:"Канефрон относится к препаратам в урологии; Кальцемин, Артифлекс и Хондромед — примеры хондропротекторов.",difficulty:"hard",tags:["препараты","торговые названия"]},{id:"musculoskeletal-diseases-035",topicId:"musculoskeletal-diseases",question:"К какой группе препаратов лекция относит Артифлекс?",options:["Ноотропы","Уросептики","Спазмолитики","Хондропротекторы"],correctIndex:3,explanation:"Артифлекс приведён в лекции среди примеров хондропротекторов.",difficulty:"easy",tags:["препараты","торговые названия"]}];export{e as default};
